css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .82); position: relative; }
.loader span { position: absolute; bottom: 5%; left: 34%; width: 32%; height: 66%; border-radius: 5px; transform-origin: bottom center; background: linear-gradient(158deg, #f8fafc, #e2e8f0); box-shadow: inset 0 0 0 2px var(--accent-2), 0 2px 6px rgba(15, 23, 42, .22); animation: fan calc(var(--loader-speed) * 2.6) cubic-bezier(.4, 0, .3, 1) infinite; }
.loader span::after { content: ''; position: absolute; top: 16%; left: 30%; width: 40%; height: 26%; background: var(--accent); clip-path: polygon(50% 0, 100% 38%, 50% 100%, 0 38%); }
.loader span:nth-child(1) { --a: -36deg; }
.loader span:nth-child(2) { --a: -18deg; animation-delay: calc(var(--loader-speed) * .07); }
.loader span:nth-child(3) { --a: 0deg; animation-delay: calc(var(--loader-speed) * .14); }
.loader span:nth-child(4) { --a: 18deg; animation-delay: calc(var(--loader-speed) * .21); }
.loader span:nth-child(5) { --a: 36deg; animation-delay: calc(var(--loader-speed) * .28); }
@keyframes fan { 0%, 12% { transform: rotate(0deg); } 44%, 70% { transform: rotate(var(--a)); } 92%, 100% { transform: rotate(0deg); } }
